using BARANG.Core.Application.Abstractions.Companies;
using BARANG.Core.Application.Abstractions.Transactions;
using BARANG.Core.Domain.Common;
using BARANG.Core.Domain.Organization;

namespace BARANG.Core.Application.Organization;

public sealed class OrganizationAdministration(IOrganizationStore store, ITransactionExecutor transactions, ICompanyContext companyContext, TimeProvider timeProvider) : IOrganizationAdministration
{
    public Task<Result<CompanyView>> CreateCompanyAsync(CreateCompanyCommand command, CancellationToken ct) => transactions.ExecuteAsync(async token =>
    {
        Result<Company> created = Company.Create(Guid.NewGuid(), command.Code, command.DisplayName, timeProvider.GetUtcNow());
        if (created.IsFailure) return Result.Failure<CompanyView>(created.Error);
        if (await store.CompanyCodeExistsAsync(created.Value.Code, token)) return Result.Failure<CompanyView>(OrganizationErrors.DuplicateCode);
        store.AddCompany(created.Value); return Result.Success(ToView(created.Value));
    }, ct);
    public async Task<Result<CompanyView>> GetCompanyAsync(Guid id, CancellationToken ct) => ToResult(await store.FindCompanyAsync(id, ct), ToView);
    public async Task<Result<IReadOnlyList<CompanyView>>> ListCompaniesAsync(CancellationToken ct) => Result.Success<IReadOnlyList<CompanyView>>((await store.ListCompaniesAsync(ct)).Select(ToView).ToArray());
    public Task<Result<CompanyView>> UpdateCompanyAsync(Guid id, string name, long version, CancellationToken ct) => ChangeCompanyAsync(id, version, company => company.UpdateDisplayName(name, timeProvider.GetUtcNow()), ct);
    public Task<Result<CompanyView>> SetCompanyActiveAsync(Guid id, bool active, long version, CancellationToken ct) => ChangeCompanyAsync(id, version, company => { if (active) company.Activate(timeProvider.GetUtcNow()); else company.Deactivate(timeProvider.GetUtcNow()); return Result.Success(); }, ct);

    public Task<Result<CompanySettingView>> CreateSettingAsync(CreateCompanySettingCommand command, CancellationToken ct) => transactions.ExecuteAsync(async token =>
    {
        Guid companyId = companyContext.RequireCompanyId();
        Result<CompanySetting> created = CompanySetting.Create(Guid.NewGuid(), companyId, command.Key, command.Value, command.ValueType, timeProvider.GetUtcNow());
        if (created.IsFailure) return Result.Failure<CompanySettingView>(created.Error);
        if (await store.SettingKeyExistsAsync(created.Value.Key, token)) return Result.Failure<CompanySettingView>(OrganizationErrors.DuplicateCode);
        store.AddSetting(created.Value); return Result.Success(ToView(created.Value));
    }, ct);
    public Task<Result<IReadOnlyList<CompanySettingView>>> ListSettingsAsync(CancellationToken ct) => InCompanyTransactionAsync(async token => Result.Success<IReadOnlyList<CompanySettingView>>((await store.ListSettingsAsync(token)).Select(ToView).ToArray()), ct);
    public Task<Result<CompanySettingView>> GetSettingAsync(Guid id, CancellationToken ct) => InCompanyTransactionAsync(async token => ToResult(await store.FindSettingAsync(id, token), ToView), ct);
    public Task<Result<CompanySettingView>> UpdateSettingAsync(Guid id, string value, CompanySettingValueType type, long version, CancellationToken ct) => ChangeScopedAsync(store.FindSettingAsync, id, version, setting => setting.Version, setting => setting.Update(value, type, timeProvider.GetUtcNow()), ToView, ct);
    public Task<Result<CompanySettingView>> DeactivateSettingAsync(Guid id, long version, CancellationToken ct) => ChangeScopedAsync(store.FindSettingAsync, id, version, setting => setting.Version, setting => { setting.Deactivate(timeProvider.GetUtcNow()); return Result.Success(); }, ToView, ct);

    public Task<Result<BranchView>> CreateBranchAsync(CreateBranchCommand command, CancellationToken ct) => transactions.ExecuteAsync(async token => { Guid companyId = companyContext.RequireCompanyId(); Result<Branch> created = Branch.Create(Guid.NewGuid(), companyId, command.Code, command.DisplayName, timeProvider.GetUtcNow()); if (created.IsFailure) return Result.Failure<BranchView>(created.Error); if (await store.BranchCodeExistsAsync(created.Value.Code, token)) return Result.Failure<BranchView>(OrganizationErrors.DuplicateCode); store.AddBranch(created.Value); return Result.Success(ToView(created.Value)); }, ct);
    public Task<Result<IReadOnlyList<BranchView>>> ListBranchesAsync(CancellationToken ct) => InCompanyTransactionAsync(async token => Result.Success<IReadOnlyList<BranchView>>((await store.ListBranchesAsync(token)).Select(ToView).ToArray()), ct);
    public Task<Result<BranchView>> GetBranchAsync(Guid id, CancellationToken ct) => InCompanyTransactionAsync(async token => ToResult(await store.FindBranchAsync(id, token), ToView), ct);
    public Task<Result<BranchView>> UpdateBranchAsync(Guid id, string name, long version, CancellationToken ct) => ChangeScopedAsync(store.FindBranchAsync, id, version, branch => branch.Version, branch => branch.Update(name, timeProvider.GetUtcNow()), ToView, ct);
    public Task<Result<BranchView>> SetBranchActiveAsync(Guid id, bool active, long version, CancellationToken ct) => ChangeScopedAsync(store.FindBranchAsync, id, version, branch => branch.Version, branch => { if (active) branch.Activate(timeProvider.GetUtcNow()); else branch.Deactivate(timeProvider.GetUtcNow()); return Result.Success(); }, ToView, ct);

    public Task<Result<OrganizationalUnitView>> CreateUnitAsync(CreateOrganizationalUnitCommand command, CancellationToken ct) => transactions.ExecuteAsync(async token => { Guid companyId = companyContext.RequireCompanyId(); if (!await ReferencesAreValidAsync(companyId, command.BranchId, command.ParentId, token)) return Result.Failure<OrganizationalUnitView>(OrganizationErrors.CrossCompanyReference); Result<OrganizationalUnit> created = OrganizationalUnit.Create(Guid.NewGuid(), companyId, command.BranchId, command.ParentId, command.Code, command.DisplayName, timeProvider.GetUtcNow()); if (created.IsFailure) return Result.Failure<OrganizationalUnitView>(created.Error); if (await store.UnitCodeExistsAsync(created.Value.Code, token)) return Result.Failure<OrganizationalUnitView>(OrganizationErrors.DuplicateCode); store.AddUnit(created.Value); return Result.Success(ToView(created.Value)); }, ct);
    public Task<Result<IReadOnlyList<OrganizationalUnitView>>> ListUnitsAsync(CancellationToken ct) => InCompanyTransactionAsync(async token => Result.Success<IReadOnlyList<OrganizationalUnitView>>((await store.ListUnitsAsync(token)).Select(ToView).ToArray()), ct);
    public Task<Result<OrganizationalUnitView>> GetUnitAsync(Guid id, CancellationToken ct) => InCompanyTransactionAsync(async token => ToResult(await store.FindUnitAsync(id, token), ToView), ct);
    public Task<Result<OrganizationalUnitView>> UpdateUnitAsync(Guid id, string name, Guid? branchId, Guid? parentId, long version, CancellationToken ct) => transactions.ExecuteAsync(async token => { Guid companyId = companyContext.RequireCompanyId(); OrganizationalUnit? unit = await store.FindUnitAsync(id, token); if (unit is null) return Result.Failure<OrganizationalUnitView>(OrganizationErrors.NotFound); if (unit.Version != version) return Result.Failure<OrganizationalUnitView>(OrganizationErrors.Concurrency); if (!await ReferencesAreValidAsync(companyId, branchId, parentId, token)) return Result.Failure<OrganizationalUnitView>(OrganizationErrors.CrossCompanyReference); if (await store.UnitWouldCreateCycleAsync(id, parentId, token)) return Result.Failure<OrganizationalUnitView>(OrganizationErrors.HierarchyCycle); Result changed = unit.Update(name, branchId, parentId, timeProvider.GetUtcNow()); return changed.IsFailure ? Result.Failure<OrganizationalUnitView>(changed.Error) : Result.Success(ToView(unit)); }, ct);
    public Task<Result<OrganizationalUnitView>> SetUnitActiveAsync(Guid id, bool active, long version, CancellationToken ct) => ChangeScopedAsync(store.FindUnitAsync, id, version, unit => unit.Version, unit => { if (active) unit.Activate(timeProvider.GetUtcNow()); else unit.Deactivate(timeProvider.GetUtcNow()); return Result.Success(); }, ToView, ct);

    public Task<Result<WarehouseView>> CreateWarehouseAsync(CreateWarehouseCommand command, CancellationToken ct) => transactions.ExecuteAsync(async token => { Guid companyId = companyContext.RequireCompanyId(); if (!await BranchIsValidAsync(command.BranchId, token)) return Result.Failure<WarehouseView>(OrganizationErrors.CrossCompanyReference); Result<Warehouse> created = Warehouse.Create(Guid.NewGuid(), companyId, command.BranchId, command.Code, command.Name, command.Type, timeProvider.GetUtcNow()); if (created.IsFailure) return Result.Failure<WarehouseView>(created.Error); if (await store.WarehouseCodeExistsAsync(created.Value.Code, token)) return Result.Failure<WarehouseView>(OrganizationErrors.DuplicateCode); store.AddWarehouse(created.Value); return Result.Success(ToView(created.Value)); }, ct);
    public Task<Result<IReadOnlyList<WarehouseView>>> ListWarehousesAsync(CancellationToken ct) => InCompanyTransactionAsync(async token => Result.Success<IReadOnlyList<WarehouseView>>((await store.ListWarehousesAsync(token)).Select(ToView).ToArray()), ct);
    public Task<Result<WarehouseView>> GetWarehouseAsync(Guid id, CancellationToken ct) => InCompanyTransactionAsync(async token => ToResult(await store.FindWarehouseAsync(id, token), ToView), ct);
    public Task<Result<WarehouseView>> UpdateWarehouseAsync(Guid id, string name, WarehouseType type, Guid? branchId, long version, CancellationToken ct) => transactions.ExecuteAsync(async token => { companyContext.RequireCompanyId(); Warehouse? warehouse = await store.FindWarehouseAsync(id, token); if (warehouse is null) return Result.Failure<WarehouseView>(OrganizationErrors.NotFound); if (warehouse.Version != version) return Result.Failure<WarehouseView>(OrganizationErrors.Concurrency); if (!await BranchIsValidAsync(branchId, token)) return Result.Failure<WarehouseView>(OrganizationErrors.CrossCompanyReference); Result changed = warehouse.Update(name, branchId, type, timeProvider.GetUtcNow()); return changed.IsFailure ? Result.Failure<WarehouseView>(changed.Error) : Result.Success(ToView(warehouse)); }, ct);
    public Task<Result<WarehouseView>> SetWarehouseActiveAsync(Guid id, bool active, long version, CancellationToken ct) => ChangeScopedAsync(store.FindWarehouseAsync, id, version, warehouse => warehouse.Version, warehouse => { if (active) warehouse.Activate(timeProvider.GetUtcNow()); else warehouse.Deactivate(timeProvider.GetUtcNow()); return Result.Success(); }, ToView, ct);

    private Task<Result<TView>> ChangeScopedAsync<TEntity, TView>(Func<Guid, CancellationToken, Task<TEntity?>> find, Guid id, long version, Func<TEntity, long> getVersion, Func<TEntity, Result> change, Func<TEntity, TView> map, CancellationToken ct) where TEntity : class => transactions.ExecuteAsync(async token => { companyContext.RequireCompanyId(); TEntity? entity = await find(id, token); if (entity is null) return Result.Failure<TView>(OrganizationErrors.NotFound); if (getVersion(entity) != version) return Result.Failure<TView>(OrganizationErrors.Concurrency); Result changed = change(entity); return changed.IsFailure ? Result.Failure<TView>(changed.Error) : Result.Success(map(entity)); }, ct);
    private Task<Result<T>> InCompanyTransactionAsync<T>(Func<CancellationToken, Task<Result<T>>> operation, CancellationToken ct) { companyContext.RequireCompanyId(); return transactions.ExecuteAsync(operation, ct); }
    private Task<Result<CompanyView>> ChangeCompanyAsync(Guid id, long version, Func<Company, Result> change, CancellationToken ct) => transactions.ExecuteAsync(async token => { Company? company = await store.FindCompanyAsync(id, token); if (company is null) return Result.Failure<CompanyView>(OrganizationErrors.NotFound); if (company.Version != version) return Result.Failure<CompanyView>(OrganizationErrors.Concurrency); Result changed = change(company); return changed.IsFailure ? Result.Failure<CompanyView>(changed.Error) : Result.Success(ToView(company)); }, ct);
    private async Task<bool> BranchIsValidAsync(Guid? branchId, CancellationToken ct) => branchId is null || await store.FindBranchAsync(branchId.Value, ct) is not null;
    private async Task<bool> ReferencesAreValidAsync(Guid companyId, Guid? branchId, Guid? parentId, CancellationToken ct) => companyId == companyContext.RequireCompanyId() && await BranchIsValidAsync(branchId, ct) && (parentId is null || await store.FindUnitAsync(parentId.Value, ct) is not null);
    private static Result<TView> ToResult<TEntity, TView>(TEntity? entity, Func<TEntity, TView> map) where TEntity : class => entity is null ? Result.Failure<TView>(OrganizationErrors.NotFound) : Result.Success(map(entity));
    private static CompanyView ToView(Company x) => new(x.Id, x.Code, x.DisplayName, x.IsActive, x.CreatedAtUtc, x.UpdatedAtUtc, x.Version);
    private static CompanySettingView ToView(CompanySetting x) => new(x.Id, x.CompanyId, x.Key, x.Value, x.ValueType, x.IsActive, x.UpdatedAtUtc, x.Version);
    private static BranchView ToView(Branch x) => new(x.Id, x.CompanyId, x.Code, x.DisplayName, x.IsActive, x.CreatedAtUtc, x.UpdatedAtUtc, x.Version);
    private static OrganizationalUnitView ToView(OrganizationalUnit x) => new(x.Id, x.CompanyId, x.BranchId, x.ParentId, x.Code, x.DisplayName, x.IsActive, x.CreatedAtUtc, x.UpdatedAtUtc, x.Version);
    private static WarehouseView ToView(Warehouse x) => new(x.Id, x.CompanyId, x.BranchId, x.Code, x.Name, x.Type, x.IsActive, x.CreatedAtUtc, x.UpdatedAtUtc, x.Version);
    internal static CompanyView ToCompanyView(Company x) => ToView(x);
    internal static BranchView ToBranchView(Branch x) => ToView(x);
    internal static OrganizationalUnitView ToUnitView(OrganizationalUnit x) => ToView(x);
}
